fix:
Walk the composition recursively without building a Vec of cloned stages. Visit inner before outer so the first refused stage in application order is still reported, and clone only the offending stage:

pub fn backdrop_image_filter_executable(filter: &ImageFilter) -> Result<(), UnsupportedImageFilter> {
    match first_backdrop_refused_stage(filter) {
        Some(stage) => Err(UnsupportedImageFilter { filter: stage.clone(), target: ImageFilterTarget::Backdrop }),
        None => Ok(()),
    }
}

/// The first dilation or erosion in application order (inner before outer), found without allocating.
fn first_backdrop_refused_stage(filter: &ImageFilter) -> Option<&ImageFilter> {
    match filter {
        ImageFilter::Compose { outer, inner } => first_backdrop_refused_stage(inner).or_else(|| first_backdrop_refused_stage(outer)),
        ImageFilter::Dilate { .. } | ImageFilter::Erode { .. } => Some(filter),
        _ => None,
    }
}

